    Bug 1923747 - Reject message transfer from nsImapProtocol to locked folders. r=darktrojan


    This changes nsImapMailFolder::ParseAdoptedMsgLine() to fail when trying to
    start a new message when the folder is locked (eg due to folder compaction).
    It also changes nsImapProtocol to check the return code from
    ParseAdoptedMsgLine() and to abort the whole operation if a failure is
    returned.

    Differential Revision: https://phabricator.services.mozilla.com/D225146

diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 586f5932931..8934c134cab 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -4328,6 +4328,23 @@ nsImapMailFolder::ParseAdoptedMsgLine(const char* adoptedMessageLine,
   uint32_t count = 0;
   nsresult rv;
   if (!m_offlineHeader) {
+    // If the folder is locked by anything other than itself,
+    // we want to fail immediately.
+    // Examples:
+    // During compaction, FolderCompactor holds the lock.
+    // During DownloadAllForOffline(), the folder locks itself.
+    bool isLocked;
+    GetLocked(&isLocked);
+    if (isLocked) {
+      // It's OK if we, the folder, have the semaphore.
+      bool hasSemaphore = false;
+      TestSemaphore(static_cast<nsIMsgFolder*>(this), &hasSemaphore);
+      if (!hasSemaphore) {
+        NS_WARNING("ParseAdoptedMsgLine: folder is locked.");
+        return NS_MSG_FOLDER_BUSY;
+      }
+    }
+
     // Starting a new message.
     if (m_curMsgUid) {
       NS_WARNING("ParseAdoptedMsgLine: already processing a message");
diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index d6d89cb9d72..8be064640f7 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -3715,8 +3715,14 @@ void nsImapProtocol::PostLineDownLoadEvent(const char* line,

     m_bytesToChannel += byteCount;
     if (m_imapMessageSink && line && echoLineToMessageSink &&
-        !GetPseudoInterrupted())
-      m_imapMessageSink->ParseAdoptedMsgLine(line, uidOfMessage, m_runningUrl);
+        !GetPseudoInterrupted()) {
+      nsresult rv = m_imapMessageSink->ParseAdoptedMsgLine(line, uidOfMessage,
+                                                           m_runningUrl);
+      if (NS_FAILED(rv)) {
+        // If the folder failed to accept the message, stop piping it across!
+        PseudoInterrupt(true);
+      }
+    }
   }
   // ***** We need to handle the pseudo interrupt here *****
 }
